```typescript
// tests/persistence.spec.ts
import { test, expect } from '@playwright/test';
import { openDB, execSQL, querySQL, closeDB } from '../helpers/db-helpers';

test.describe('OPFS Persistence', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await page.waitForFunction(() => (window as any).__frankendb_ready);
  });

  test('data survives full page reload', async ({ page }) => {
    const dbName = `persist_test_${Date.now()}`;
    console.log(`[T.2] Opening DB: ${dbName}`);

    await openDB(page, dbName);
    await execSQL(page, 'CREATE TABLE notes (id INTEGER PRIMARY KEY, body TEXT)');
    await execSQL(page, "INSERT INTO notes (body) VALUES ('survive reload')");

    const beforeReload = await querySQL(page, 'SELECT * FROM notes');
    console.log(`[T.2] Before reload: ${JSON.stringify(beforeReload)}`);
    expect(beforeReload).toHaveLength(1);
    expect(beforeReload[0].body).toBe('survive reload');

    await closeDB(page);
    console.log('[T.2] DB closed, reloading page...');

    await page.reload();
    await page.waitForFunction(() => (window as any).__frankendb_ready);

    await openDB(page, dbName);
    const afterReload = await querySQL(page, 'SELECT * FROM notes');
    console.log(`[T.2] After reload: ${JSON.stringify(afterReload)}`);
    expect(afterReload).toHaveLength(1);
    expect(afterReload[0].body).toBe('survive reload');

    // Cleanup
    await closeDB(page);
    console.log('[T.2] PASS: Data survived page reload via OPFS');
  });

  test('multiple databases persist independently', async ({ page }) => {
    const db1 = `multi_a_${Date.now()}`;
    const db2 = `multi_b_${Date.now()}`;

    await openDB(page, db1);
    await execSQL(page, "CREATE TABLE t (v TEXT)");
    await execSQL(page, "INSERT INTO t VALUES ('alpha')");
    await closeDB(page);

    await openDB(page, db2);
    await execSQL(page, "CREATE TABLE t (v TEXT)");
    await execSQL(page, "INSERT INTO t VALUES ('beta')");
    await closeDB(page);

    await page.reload();
    await page.waitForFunction(() => (window as any).__frankendb_ready);

    await openDB(page, db1);
    const r1 = await querySQL(page, 'SELECT v FROM t');
    expect(r1[0].v).toBe('alpha');
    await closeDB(page);

    await openDB(page, db2);
    const r2 = await querySQL(page, 'SELECT v FROM t');
    expect(r2[0].v).toBe('beta');
    await closeDB(page);

    console.log('[T.2] PASS: Independent databases persist correctly');
  });
});
