# 5I.7: Comprehensive Index Maintenance Test Suite

## Objective

Create a thorough test suite that validates index maintenance across all DML operations and edge cases. These tests should catch regressions and serve as the acceptance criteria for Phase 5I completion.

## Test Categories

### 1. Basic Operations

```rust
#[test] fn test_insert_single_column_index() { ... }
#[test] fn test_insert_multi_column_index() { ... }
#[test] fn test_delete_removes_index_entry() { ... }
#[test] fn test_update_indexed_column() { ... }
#[test] fn test_update_non_indexed_column() { ... }
```

### 2. Multiple Indexes

```rust
#[test]
fn test_multiple_indexes_on_table() {
    let conn = Connection::open(":memory:").unwrap();
    conn.execute("CREATE TABLE t (a INT, b INT, c INT, d INT)").unwrap();
    conn.execute("CREATE INDEX idx_a ON t(a)").unwrap();
    conn.execute("CREATE INDEX idx_b ON t(b)").unwrap();
    conn.execute("CREATE INDEX idx_ab ON t(a, b)").unwrap();
    conn.execute("CREATE INDEX idx_cd ON t(c, d)").unwrap();

    conn.execute("INSERT INTO t VALUES (1, 2, 3, 4)").unwrap();

    // All indexes should be searchable
    assert_query_returns_row("SELECT * FROM t WHERE a = 1");
    assert_query_returns_row("SELECT * FROM t WHERE b = 2");
    assert_query_returns_row("SELECT * FROM t WHERE a = 1 AND b = 2");
    assert_query_returns_row("SELECT * FROM t WHERE c = 3 AND d = 4");
}
```

### 3. NULL Handling

```rust
#[test]
fn test_index_with_null_values() {
    let conn = Connection::open(":memory:").unwrap();
    conn.execute("CREATE TABLE t (id INT, name TEXT)").unwrap();
    conn.execute("CREATE INDEX idx_name ON t(name)").unwrap();

    conn.execute("INSERT INTO t VALUES (1, NULL)").unwrap();
    conn.execute("INSERT INTO t VALUES (2, 'alice')").unwrap();
    conn.execute("INSERT INTO t VALUES (3, NULL)").unwrap();

    // Query for NULL
    let rows = conn.query("SELECT id FROM t WHERE name IS NULL").unwrap();
    assert_eq!(rows.len(), 2);  // Both NULL rows

    // Update NULL to non-NULL
    conn.execute("UPDATE t SET name = 'bob' WHERE id = 1").unwrap();

    let rows = conn.query("SELECT id FROM t WHERE name IS NULL").unwrap();
    assert_eq!(rows.len(), 1);  // Only id=3 now
}
```

### 4. UNIQUE Index Constraints

```rust
#[test]
fn test_unique_index_insert_conflict() {
    let conn = Connection::open(":memory:").unwrap();
    conn.execute("CREATE TABLE t (id INT, email TEXT)").unwrap();
    conn.execute("CREATE UNIQUE INDEX idx_email ON t(email)").unwrap();

    conn.execute("INSERT INTO t VALUES (1, 'a@b.com')").unwrap();

    let result = conn.execute("INSERT INTO t VALUES (2, 'a@b.com')");
    assert!(result.is_err());  // UNIQUE violation
}

#[test]
fn test_unique_index_update_conflict() {
    let conn = Connection::open(":memory:").unwrap();
    conn.execute("CREATE TABLE t (id INT, email TEXT)").unwrap();
    conn.execute("CREATE UNIQUE INDEX idx_email ON t(email)").unwrap();

    conn.execute("INSERT INTO t VALUES (1, 'a@b.com')").unwrap();
    conn.execute("INSERT INTO t VALUES (2, 'b@b.com')").unwrap();

    let result = conn.execute("UPDATE t SET email = 'a@b.com' WHERE id = 2");
    assert!(result.is_err());  // UNIQUE violation
}
```

### 5. Bulk Operations

```rust
#[test]
fn test_bulk_insert_index_maintenance() {
    let conn = Connection::open(":memory:").unwrap();
    conn.execute("CREATE TABLE t (id INT, value INT)").unwrap();
    conn.execute("CREATE INDEX idx_value ON t(value)").unwrap();

    // Insert 1000 rows
    for i in 0..1000 {
        conn.execute(&format!("INSERT INTO t VALUES ({}, {})", i, i * 2)).unwrap();
    }

    // Verify index works for various values
    for i in [0, 100, 500, 999] {
        let rows = conn.query(&format!("SELECT id FROM t WHERE value = {}", i * 2)).unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].get(0), SqliteValue::Integer(i));
    }
}

#[test]
fn test_bulk_delete_index_maintenance() {
    // Similar test for DELETE
}
```

### 6. Transaction Rollback

```rust
#[test]
fn test_index_rollback() {
    let conn = Connection::open(":memory:").unwrap();
    conn.execute("CREATE TABLE t (id INT, name TEXT)").unwrap();
    conn.execute("CREATE INDEX idx_name ON t(name)").unwrap();
    conn.execute("INSERT INTO t VALUES (1, 'alice')").unwrap();

    conn.execute("BEGIN").unwrap();
    conn.execute("INSERT INTO t VALUES (2, 'bob')").unwrap();

    // Bob should be visible in transaction
    let rows = conn.query("SELECT id FROM t WHERE name = 'bob'").unwrap();
    assert_eq!(rows.len(), 1);

    conn.execute("ROLLBACK").unwrap();

    // Bob should NOT be visible after rollback
    let rows = conn.query("SELECT id FROM t WHERE name = 'bob'").unwrap();
    assert_eq!(rows.len(), 0);

    // Alice should still be there
    let rows = conn.query("SELECT id FROM t WHERE name = 'alice'").unwrap();
    assert_eq!(rows.len(), 1);
}
```

