// src/components/TodoList.tsx
import { useQuery } from '@frankensqlite/react';

interface Todo {
  id: number;
  title: string;
  done: number;
  created_at: string;
}

export function TodoList({ filter }: { filter: 'all' | 'active' | 'done' }) {
  const where = filter === 'all' ? '' : filter === 'active' ? 'WHERE done = 0' : 'WHERE done = 1';
  const { data, isLoading, error } = useQuery<Todo>(
    `SELECT * FROM todos ${where} ORDER BY created_at DESC`
  );

  if (isLoading) return <div className="loading">Loading todos...</div>;
  if (error) return <div className="error">Error: {error.message}</div>;

  console.log(`[TodoList] Rendered ${data.length} todos (filter: ${filter})`);

  return (
    <ul className="todo-list">
      {data.map(todo => (
        <TodoItem key={todo.id} todo={todo} />
      ))}
      {data.length === 0 && <li className="empty">No todos yet!</li>}
    </ul>
  );
}
```

