### Key Feature: Autosave Hook
```typescript
// src/hooks/useAutosave.ts
import { useCallback, useEffect, useRef } from 'react';
import { useMutation } from '@frankensqlite/react';

export function useAutosave(noteId: number, content: string, delayMs = 1000) {
  const { mutate } = useMutation();
  const timeoutRef = useRef<NodeJS.Timeout>();
  const lastSavedRef = useRef(content);

  const save = useCallback(async (text: string) => {
    if (text === lastSavedRef.current) return;
    console.log(`[autosave] Saving note ${noteId} (${text.length} chars)`);
    await mutate(
      'UPDATE notes SET content = ?, updated_at = datetime("now") WHERE id = ?',
      [text, noteId],
      { invalidate: ['notes'] }
    );
    lastSavedRef.current = text;
    console.log(`[autosave] Saved note ${noteId}`);
  }, [noteId, mutate]);

  useEffect(() => {
    clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => save(content), delayMs);
    return () => clearTimeout(timeoutRef.current);
  }, [content, delayMs, save]);

  // Save immediately on unmount
  useEffect(() => {
    return () => { save(content); };
  }, []);
}
```

