```

### 3. SRI Hash Generation Script
```bash
#!/bin/bash
# scripts/generate-integrity.sh
# Generate SRI hashes for all CDN-distributed files

OUTPUT="cdn/integrity.json"
echo '{' > "$OUTPUT"

for file in dist/frankensqlite.umd.min.js dist/frankensqlite_bg.wasm dist/frankensqlite.worker.js cdn/frankensqlite.iife.min.js; do
  if [ -f "$file" ]; then
    HASH=$(cat "$file" | openssl dgst -sha384 -binary | openssl base64 -A)
    SIZE=$(stat -c%s "$file")
    echo "  \"$file\": {" >> "$OUTPUT"
    echo "    \"integrity\": \"sha384-$HASH\"," >> "$OUTPUT"
    echo "    \"size\": $SIZE" >> "$OUTPUT"
    echo "  }," >> "$OUTPUT"
    echo "[integrity] $file: sha384-$HASH ($SIZE bytes)"
  fi
done

# Remove trailing comma, close JSON
sed -i '$ s/,$//' "$OUTPUT"
echo '}' >> "$OUTPUT"
echo "[integrity] Generated $OUTPUT"
```

