## Store Pattern (useSyncExternalStore integration)
```typescript
// src/store.ts
type Listener = () => void;

export class QueryStore<T> {
  private data: T[] = [];
  private loading = true;
  private error: Error | null = null;
  private listeners = new Set<Listener>();
  private version = 0;

  subscribe = (listener: Listener): (() => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  getSnapshot = (): { data: T[]; isLoading: boolean; error: Error | null; version: number } => {
    return { data: this.data, isLoading: this.loading, error: this.error, version: this.version };
  };

  // NOTE: getServerSnapshot returns empty/loading state for SSR safety
  getServerSnapshot = (): { data: T[]; isLoading: boolean; error: Error | null; version: number } => {
    return { data: [], isLoading: true, error: null, version: 0 };
  };

  update(data: T[]) {
    this.data = data;
    this.loading = false;
    this.error = null;
    this.version++;
    this.notify();
  }

  setError(error: Error) {
    this.error = error;
    this.loading = false;
    this.version++;
    this.notify();
  }

  private notify() {
    for (const l of this.listeners) l();
  }
}
```

