```typescript
// run-conformance.spec.ts
import { test, expect } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { openDB, execSQL, querySQL, closeDB } from '../tests-e2e/helpers/db-helpers';

const FIXTURES_DIR = path.join(__dirname, 'fixtures/generated');
const WASM_SPECIFIC_DIR = path.join(__dirname, 'fixtures/wasm-specific');

function loadFixtures(dir: string): any[] {
  const suites: any[] = [];
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json'))) {
    suites.push(JSON.parse(fs.readFileSync(path.join(dir, file), 'utf-8')));
  }
  return suites;
}

for (const suite of [...loadFixtures(FIXTURES_DIR), ...loadFixtures(WASM_SPECIFIC_DIR)]) {
  test.describe(`Conformance: ${suite.suite}`, () => {
    for (const tc of suite.cases) {
      test(tc.name, async ({ page }) => {
        await page.goto('/');
        await page.waitForFunction(() => (window as any).__frankendb_ready);

        const dbName = `conform_${suite.suite}_${tc.name}_${Date.now()}`;
        await openDB(page, dbName);

        // Setup
        for (const s of tc.setup ?? []) {
          console.log(`[T.3:${tc.name}] setup: ${s}`);
          await execSQL(page, s);
        }

        // Execute test SQL (may be multi-statement)
        const statements = tc.sql.split(';').filter((s: string) => s.trim());
        let lastResult: any[] = [];
        for (const stmt of statements) {
          const trimmed = stmt.trim();
          if (!trimmed) continue;
          console.log(`[T.3:${tc.name}] exec: ${trimmed}`);
          if (trimmed.toUpperCase().startsWith('SELECT') ||
              trimmed.toUpperCase().startsWith('PRAGMA') ||
              trimmed.toUpperCase().startsWith('VALUES')) {
            lastResult = await querySQL(page, trimmed);
          } else {
            await execSQL(page, trimmed);
          }
        }

        // Compare results
        console.log(`[T.3:${tc.name}] expected: ${JSON.stringify(tc.expected)}`);
        console.log(`[T.3:${tc.name}] actual:   ${JSON.stringify(lastResult)}`);

        expect(lastResult).toHaveLength(tc.expected.length);
        for (let i = 0; i < tc.expected.length; i++) {
          for (const [col, expectedVal] of Object.entries(tc.expected[i])) {
            const actualVal = lastResult[i][col];
            if (typeof expectedVal === 'number' && !Number.isInteger(expectedVal)) {
              // Float comparison with tolerance
              expect(Math.abs((actualVal as number) - (expectedVal as number)))
                .toBeLessThan(1e-10);
            } else {
              expect(actualVal).toEqual(expectedVal);
            }
          }
        }

        // Teardown
        for (const s of tc.teardown ?? []) {
          await execSQL(page, s);
        }
        await closeDB(page);
        console.log(`[T.3:${tc.name}] PASS`);
      });
    }
  });
}
