# Task 2.2: Core wasm-bindgen API Surface

## What
Implement the primary JavaScript-facing API: FrankenDB class with execute(), query(), prepare() methods.

## Implementation

### FrankenDB Class
```rust
#[wasm_bindgen]
pub struct FrankenDB {
    conn: Connection,
}

#[wasm_bindgen]
impl FrankenDB {
    #[wasm_bindgen(constructor)]
    pub fn new() -> Result<FrankenDB, JsValue> {
        console_error_panic_hook::set_once();
        Connection::open(":memory:")
            .map(|conn| FrankenDB { conn })
            .map_err(to_js_error)
    }

    #[wasm_bindgen(js_name = "execute")]
    pub fn execute(&self, sql: &str) -> Result<usize, JsValue> {
        self.conn.execute(sql).map_err(to_js_error)
    }

    #[wasm_bindgen(js_name = "query")]
    pub fn query(&self, sql: &str) -> Result<JsValue, JsValue> {
        let rows = self.conn.query(sql).map_err(to_js_error)?;
        serde_wasm_bindgen::to_value(&rows).map_err(to_js_error)
    }

    #[wasm_bindgen(js_name = "queryWithParams")]
    pub fn query_with_params(&self, sql: &str, params: JsValue) -> Result<JsValue, JsValue> {
