## Benchmark Suite: INSERT Performance
```typescript
// src/suites/insert.ts
import type { DBAdapter } from '../types';

export async function benchmarkInsert(db: DBAdapter): Promise<BenchmarkResult[]> {
  const results: BenchmarkResult[] = [];

  // Warmup
  await db.execute('CREATE TABLE IF NOT EXISTS bench_insert (id INTEGER PRIMARY KEY, val TEXT, num REAL)');
  await db.execute('DELETE FROM bench_insert');

  // 1. Single INSERT (1000 iterations)
  const singleStart = performance.now();
  for (let i = 0; i < 1000; i++) {
    await db.execute(`INSERT INTO bench_insert VALUES (${i}, 'value_${i}', ${Math.random()})`);
  }
  const singleMs = performance.now() - singleStart;
  results.push({
    name: 'single_insert_1k',
    ops: 1000,
    totalMs: singleMs,
    opsPerSec: Math.round(1000 / (singleMs / 1000)),
  });
  console.log(`[bench] Single INSERT: ${singleMs.toFixed(1)}ms (${results[0].opsPerSec} ops/sec)`);

  // Cleanup
  await db.execute('DELETE FROM bench_insert');

  // 2. Batched INSERT in transaction (10K rows)
  const batchStart = performance.now();
  await db.execute('BEGIN');
  for (let i = 0; i < 10_000; i++) {
    await db.execute(`INSERT INTO bench_insert VALUES (${i}, 'batch_${i}', ${Math.random()})`);
  }
  await db.execute('COMMIT');
  const batchMs = performance.now() - batchStart;
  results.push({
    name: 'batch_insert_10k_txn',
    ops: 10_000,
    totalMs: batchMs,
    opsPerSec: Math.round(10_000 / (batchMs / 1000)),
  });
  console.log(`[bench] Batch INSERT (txn): ${batchMs.toFixed(1)}ms (${results[1].opsPerSec} ops/sec)`);

  // 3. Large row INSERT (1KB text per row, 1000 rows)
  await db.execute('DELETE FROM bench_insert');
  const largeText = 'x'.repeat(1024);
  const largeStart = performance.now();
  await db.execute('BEGIN');
  for (let i = 0; i < 1000; i++) {
    await db.execute(`INSERT INTO bench_insert VALUES (${i}, '${largeText}', ${i})`);
  }
  await db.execute('COMMIT');
  const largeMs = performance.now() - largeStart;
  results.push({
    name: 'large_row_insert_1k',
    ops: 1000,
    totalMs: largeMs,
    opsPerSec: Math.round(1000 / (largeMs / 1000)),
  });
  console.log(`[bench] Large row INSERT: ${largeMs.toFixed(1)}ms`);

  await db.execute('DROP TABLE bench_insert');
  return results;
}
```

